insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','missed-workout','What if I miss a workout?','Leave the missed session behind and choose the next realistic slot.','Training','planner','Leave the missed session behind and choose the next realistic slot. Do not squeeze two hard sessions into one day to catch up. Keep the remaining week manageable; if this keeps happening, ask your coach to adjust the schedule.','Open your weekly planner. Identify one session you can actually attend, then discuss moving the missed session with your coach. A missed session is useful information about your schedule, not a debt. Tell your coach which deadline, commute or family commitment got in the way so the next week can be more realistic.','HOOK (5–10s): What if I miss a workout?
EXPLANATION (30–90s): Leave the missed session behind and choose the next realistic slot. Do not squeeze two hard sessions into one day to catch up. Keep the remaining week manageable; if this keeps happening, ask your coach to adjust the schedule. Open your weekly planner. Identify one session you can actually attend, then discuss moving the missed session with your coach. A missed session is useful information about your schedule, not a debt. Tell your coach which deadline, commute or family commitment got in the way so the next week can be more realistic.
ACTION (10–20s): Open your weekly planner. Bring the recurring obstacle to your next check-in.','["What if I miss a workout?", "The practical principle", "What the evidence can and cannot tell us", "Open your weekly planner", "Your decision: Open your weekly planner", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "WHO physical activity guidance (general context)", "url": "https://www.who.int/news-room/fact-sheets/detail/physical-activity"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['emergency-workout','travel-training']::text[],'Training What if I miss a workout? busy work travel time','reviewed',true) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','emergency-workout','The 20-minute emergency workout','Use a shorter version of your assigned session, approved by your coach.','Training','workout','Use a shorter version of your assigned session, approved by your coach. Keep the warm-up and the important movements. Reduce extra work before rushing rests or technique. Preview the option before accepting; if none is approved, ask your coach.','A time limit does not mean you need a new workout. Your coach can choose which assigned movements to retain and how many sets to perform. The tool shows that exact option, keeps your original session and records your choice. The displayed time is a planning window, not a promise that every person will finish at the same pace.','HOOK (5–10s): The 20-minute emergency workout
EXPLANATION (30–90s): Use a shorter version of your assigned session, approved by your coach. Keep the warm-up and the important movements. Reduce extra work before rushing rests or technique. Preview the option before accepting; if none is approved, ask your coach. A time limit does not mean you need a new workout. Your coach can choose which assigned movements to retain and how many sets to perform. The tool shows that exact option, keeps your original session and records your choice. The displayed time is a planning window, not a promise that every person will finish at the same pace.
ACTION (10–20s): Preview a coach-approved workout option. Bring the recurring obstacle to your next check-in.','["The 20-minute emergency workout", "The practical principle", "What the evidence can and cannot tell us", "A time limit does not mean you need a new workout", "Your decision: Preview a coach-approved workout option", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "WHO physical activity guidance (general context)", "url": "https://www.who.int/news-room/fact-sheets/detail/physical-activity"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['missed-workout','travel-training']::text[],'Training The 20-minute emergency workout busy work travel time','reviewed',true) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','demanding-week','Training during a 60–70-hour work week','Plan around the week you have, not your ideal week.','Training','planner','Plan around the week you have, not your ideal week. Protect the most reliable training slot first, then a second if it fits. Ask your coach which sessions matter most. A short approved session is more useful than a plan you cannot attend.','Look at your calendar before booking training. Court dates, travel and late meetings are constraints the programme should accommodate. Choose a realistic location and leave time for travel and changing. If even the reduced week is not workable, message your coach instead of repeatedly moving sessions without review.','HOOK (5–10s): Training during a 60–70-hour work week
EXPLANATION (30–90s): Plan around the week you have, not your ideal week. Protect the most reliable training slot first, then a second if it fits. Ask your coach which sessions matter most. A short approved session is more useful than a plan you cannot attend. Look at your calendar before booking training. Court dates, travel and late meetings are constraints the programme should accommodate. Choose a realistic location and leave time for travel and changing. If even the reduced week is not workable, message your coach instead of repeatedly moving sessions without review.
ACTION (10–20s): Open your weekly planner. Bring the recurring obstacle to your next check-in.','["Training during a 60–70-hour work week", "The practical principle", "What the evidence can and cannot tell us", "Look at your calendar before booking training", "Your decision: Open your weekly planner", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "WHO physical activity guidance (general context)", "url": "https://www.who.int/news-room/fact-sheets/detail/physical-activity"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['missed-workout','emergency-workout','travel-training']::text[],'Training Training during a 60–70-hour work week busy work travel time','reviewed',true) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','three-sessions','Making progress with three sessions per week','Three consistent sessions can give your coach plenty to work with.','Training','training','Three consistent sessions can give your coach plenty to work with. Follow the assigned movements, record the work and recover between sessions. Judge progress across weeks rather than adding extra sessions because one day felt easy.','Frequency is one part of a programme alongside exercise selection, effort, volume and recovery. Your assigned three-session plan should reflect your goals and experience. Use the training log to show your coach what happened. If attendance is reliable but progress is unclear, review the plan together before increasing workload.','HOOK (5–10s): Making progress with three sessions per week
EXPLANATION (30–90s): Three consistent sessions can give your coach plenty to work with. Follow the assigned movements, record the work and recover between sessions. Judge progress across weeks rather than adding extra sessions because one day felt easy. Frequency is one part of a programme alongside exercise selection, effort, volume and recovery. Your assigned three-session plan should reflect your goals and experience. Use the training log to show your coach what happened. If attendance is reliable but progress is unclear, review the plan together before increasing workload.
ACTION (10–20s): Open your training. Bring the recurring obstacle to your next check-in.','["Making progress with three sessions per week", "The practical principle", "What the evidence can and cannot tell us", "Frequency is one part of a programme alongside exercise selection, effort, volume and recovery", "Your decision: Open your training", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "WHO physical activity guidance (general context)", "url": "https://www.who.int/news-room/fact-sheets/detail/physical-activity"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['missed-workout','emergency-workout','travel-training']::text[],'Training Making progress with three sessions per week busy work travel time','reviewed',false) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','busy-gym','What to do when the gym is busy','Check the alternatives your coach attached to the exercise.','Training','training','Check the alternatives your coach attached to the exercise. Use an approved option with equipment you can access. If there is no suitable alternative, move to another assigned movement or ask your coach; do not copy the original load onto unfamiliar equipment.','A substitute should preserve the intent of the movement and suit your experience and limitations. Machines, cables and free weights can feel very different. Read the saved instructions and record the equipment you used so the coach can interpret your performance. Your existing exercise-options controls hold approved substitutions.','HOOK (5–10s): What to do when the gym is busy
EXPLANATION (30–90s): Check the alternatives your coach attached to the exercise. Use an approved option with equipment you can access. If there is no suitable alternative, move to another assigned movement or ask your coach; do not copy the original load onto unfamiliar equipment. A substitute should preserve the intent of the movement and suit your experience and limitations. Machines, cables and free weights can feel very different. Read the saved instructions and record the equipment you used so the coach can interpret your performance. Your existing exercise-options controls hold approved substitutions.
ACTION (10–20s): Open your training. Bring the recurring obstacle to your next check-in.','["What to do when the gym is busy", "The practical principle", "What the evidence can and cannot tell us", "A substitute should preserve the intent of the movement and suit your experience and limitations", "Your decision: Open your training", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "WHO physical activity guidance (general context)", "url": "https://www.who.int/news-room/fact-sheets/detail/physical-activity"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['missed-workout','emergency-workout','travel-training']::text[],'Training What to do when the gym is busy busy work travel time','reviewed',false) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','travel-training','Training while travelling','Check the hotel equipment before you leave.','Training','travel','Check the hotel equipment before you leave. Use an existing assigned travel session or a coach-approved hotel option. If the equipment does not fit, ask for an alternative rather than inventing a circuit. Put one realistic training slot into your travel calendar.','Send your coach the hotel equipment list or a photo before the trip. Discuss which session can move and which shorter option is useful. Walking and mobility can help keep a routine, but do not treat them as a replacement prescription without agreeing it. Travel mode links to your programme and planner, rather than creating a second schedule.','HOOK (5–10s): Training while travelling
EXPLANATION (30–90s): Check the hotel equipment before you leave. Use an existing assigned travel session or a coach-approved hotel option. If the equipment does not fit, ask for an alternative rather than inventing a circuit. Put one realistic training slot into your travel calendar. Send your coach the hotel equipment list or a photo before the trip. Discuss which session can move and which shorter option is useful. Walking and mobility can help keep a routine, but do not treat them as a replacement prescription without agreeing it. Travel mode links to your programme and planner, rather than creating a second schedule.
ACTION (10–20s): Open travel support. Bring the recurring obstacle to your next check-in.','["Training while travelling", "The practical principle", "What the evidence can and cannot tell us", "Send your coach the hotel equipment list or a photo before the trip", "Your decision: Open travel support", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "WHO physical activity guidance (general context)", "url": "https://www.who.int/news-room/fact-sheets/detail/physical-activity"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['missed-workout','emergency-workout']::text[],'Training Training while travelling busy work travel time','reviewed',true) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','late-office','Eating well during late office nights','Choose the next practical meal from your assigned options.','Nutrition','meal','Choose the next practical meal from your assigned options. Look for a familiar protein source, a carbohydrate you enjoy and vegetables where available. Keep a reliable backup at work. An imperfect dinner is usually easier to recover from than abandoning your routine.','Before a predictable late night, decide where food will come from and when you can take a break. Use an assigned portable meal if its storage and ingredients suit you. When ordering out, choose foods you recognise and check ingredients and allergens with the seller. Restaurant portions and nutritional values are uncertain; the app will not make them up.','HOOK (5–10s): Eating well during late office nights
EXPLANATION (30–90s): Choose the next practical meal from your assigned options. Look for a familiar protein source, a carbohydrate you enjoy and vegetables where available. Keep a reliable backup at work. An imperfect dinner is usually easier to recover from than abandoning your routine. Before a predictable late night, decide where food will come from and when you can take a break. Use an assigned portable meal if its storage and ingredients suit you. When ordering out, choose foods you recognise and check ingredients and allergens with the seller. Restaurant portions and nutritional values are uncertain; the app will not make them up.
ACTION (10–20s): Choose from your assigned meals. Bring the recurring obstacle to your next check-in.','["Eating well during late office nights", "The practical principle", "What the evidence can and cannot tell us", "Before a predictable late night, decide where food will come from and when you can take a break", "Your decision: Choose from your assigned meals", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "NHS balanced eating guidance (general context)", "url": "https://www.nhs.uk/live-well/eat-well/how-to-eat-a-balanced-diet/eating-a-balanced-diet/"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['restaurants','meal-prep']::text[],'Nutrition Eating well during late office nights busy work travel time','reviewed',true) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','restaurants','Ordering food at restaurants','Choose a meal you enjoy with a recognisable protein source and a portion that feels comfortable.','Nutrition','meal','Choose a meal you enjoy with a recognisable protein source and a portion that feels comfortable. Ask about ingredients and allergens. Use your plan as a guide, not a requirement to calculate every bite during a client dinner.','Review the actual menu when you can. Preparation, sauces and portions vary, so an app cannot guarantee a restaurant meal matches a saved recipe. If you have an allergy, speak to the restaurant directly about preparation and cross-contact. A busy dinner can still fit your routine; tell your coach about repeated situations that need a practical strategy.','HOOK (5–10s): Ordering food at restaurants
EXPLANATION (30–90s): Choose a meal you enjoy with a recognisable protein source and a portion that feels comfortable. Ask about ingredients and allergens. Use your plan as a guide, not a requirement to calculate every bite during a client dinner. Review the actual menu when you can. Preparation, sauces and portions vary, so an app cannot guarantee a restaurant meal matches a saved recipe. If you have an allergy, speak to the restaurant directly about preparation and cross-contact. A busy dinner can still fit your routine; tell your coach about repeated situations that need a practical strategy.
ACTION (10–20s): Choose from your assigned meals. Bring the recurring obstacle to your next check-in.','["Ordering food at restaurants", "The practical principle", "What the evidence can and cannot tell us", "Review the actual menu when you can", "Your decision: Choose from your assigned meals", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "NHS balanced eating guidance (general context)", "url": "https://www.nhs.uk/live-well/eat-well/how-to-eat-a-balanced-diet/eating-a-balanced-diet/"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['late-office','meal-prep']::text[],'Nutrition Ordering food at restaurants busy work travel time','reviewed',true) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','protein-portions','Protein without weighing everything','Use the protein foods and portions already shown in your plan as a reference.','Nutrition','nutrition','Use the protein foods and portions already shown in your plan as a reference. Repeating a few familiar breakfasts and lunches makes this easier. If weighing is getting in the way, ask your coach for household measures that fit those meals.','A portion guide is a practical approximation, not a precise nutrient calculation. Different foods and serving sizes vary. Your coach can translate assigned recipes into everyday measures and decide how much precision your goal needs. Do not increase protein targets yourself or assume a general recommendation fits a medical condition.','HOOK (5–10s): Protein without weighing everything
EXPLANATION (30–90s): Use the protein foods and portions already shown in your plan as a reference. Repeating a few familiar breakfasts and lunches makes this easier. If weighing is getting in the way, ask your coach for household measures that fit those meals. A portion guide is a practical approximation, not a precise nutrient calculation. Different foods and serving sizes vary. Your coach can translate assigned recipes into everyday measures and decide how much precision your goal needs. Do not increase protein targets yourself or assume a general recommendation fits a medical condition.
ACTION (10–20s): Open your meal plan. Bring the recurring obstacle to your next check-in.','["Protein without weighing everything", "The practical principle", "What the evidence can and cannot tell us", "A portion guide is a practical approximation, not a precise nutrient calculation", "Your decision: Open your meal plan", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "NHS balanced eating guidance (general context)", "url": "https://www.nhs.uk/live-well/eat-well/how-to-eat-a-balanced-diet/eating-a-balanced-diet/"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['late-office','restaurants','meal-prep']::text[],'Nutrition Protein without weighing everything busy work travel time','reviewed',false) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','travel-food','Nutrition during business travel','Pick one dependable breakfast and a portable backup before travelling.','Nutrition','meal','Pick one dependable breakfast and a portable backup before travelling. Plan where the next meal is likely to come from. Choose familiar ingredients and check allergens. Return to your normal plan at the next convenient meal, without trying to compensate for the whole trip.','Look at travel timing: early departure, airport wait, hotel arrival and client dinners. Where permitted and safely stored, an assigned portable meal can bridge a long gap. At an airport, assess actual options rather than relying on a fictional menu. Keep the trip workable and bring the recurring obstacles to your next check-in.','HOOK (5–10s): Nutrition during business travel
EXPLANATION (30–90s): Pick one dependable breakfast and a portable backup before travelling. Plan where the next meal is likely to come from. Choose familiar ingredients and check allergens. Return to your normal plan at the next convenient meal, without trying to compensate for the whole trip. Look at travel timing: early departure, airport wait, hotel arrival and client dinners. Where permitted and safely stored, an assigned portable meal can bridge a long gap. At an airport, assess actual options rather than relying on a fictional menu. Keep the trip workable and bring the recurring obstacles to your next check-in.
ACTION (10–20s): Choose from your assigned meals. Bring the recurring obstacle to your next check-in.','["Nutrition during business travel", "The practical principle", "What the evidence can and cannot tell us", "Look at travel timing: early departure, airport wait, hotel arrival and client dinners", "Your decision: Choose from your assigned meals", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "NHS balanced eating guidance (general context)", "url": "https://www.nhs.uk/live-well/eat-well/how-to-eat-a-balanced-diet/eating-a-balanced-diet/"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['late-office','restaurants','meal-prep']::text[],'Nutrition Nutrition during business travel busy work travel time','reviewed',true) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','overeating','What to do after overeating','Return to your usual next meal.','Nutrition','nutrition','Return to your usual next meal. Avoid skipping food or adding punishment exercise to compensate. Notice what led up to it: a long gap, stress, alcohol or an unusually large portion. One meal does not require rewriting your targets.','Review the circumstances without turning one event into a judgement about yourself. A practical change might be eating before a long meeting or keeping a backup meal available. If eating feels out of control, repeatedly distressing or involves compensatory behaviours, tell your coach and seek support from a qualified clinician. The app is not an eating-disorder treatment.','HOOK (5–10s): What to do after overeating
EXPLANATION (30–90s): Return to your usual next meal. Avoid skipping food or adding punishment exercise to compensate. Notice what led up to it: a long gap, stress, alcohol or an unusually large portion. One meal does not require rewriting your targets. Review the circumstances without turning one event into a judgement about yourself. A practical change might be eating before a long meeting or keeping a backup meal available. If eating feels out of control, repeatedly distressing or involves compensatory behaviours, tell your coach and seek support from a qualified clinician. The app is not an eating-disorder treatment.
ACTION (10–20s): Open your meal plan. Bring the recurring obstacle to your next check-in.','["What to do after overeating", "The practical principle", "What the evidence can and cannot tell us", "Review the circumstances without turning one event into a judgement about yourself", "Your decision: Open your meal plan", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "NHS balanced eating guidance (general context)", "url": "https://www.nhs.uk/live-well/eat-well/how-to-eat-a-balanced-diet/eating-a-balanced-diet/"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['late-office','restaurants','meal-prep']::text[],'Nutrition What to do after overeating busy work travel time','reviewed',true) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','meal-prep','Meal preparation for busy professionals','Prepare one or two useful meals rather than an entire perfect week.','Nutrition','nutrition','Prepare one or two useful meals rather than an entire perfect week. Use your assigned recipes, make a realistic number of servings and plan safe storage. A reliable lunch and backup dinner can solve more problems than a complicated Sunday cooking session.','Choose recipes you already enjoy and check your shopping list before cooking. Batch preparation changes the number of portions, not the serving size in your daily log. Label leftovers and follow local food-safety guidance for refrigeration, reheating and transport. If facilities are limited, ask for meals that fit those constraints.','HOOK (5–10s): Meal preparation for busy professionals
EXPLANATION (30–90s): Prepare one or two useful meals rather than an entire perfect week. Use your assigned recipes, make a realistic number of servings and plan safe storage. A reliable lunch and backup dinner can solve more problems than a complicated Sunday cooking session. Choose recipes you already enjoy and check your shopping list before cooking. Batch preparation changes the number of portions, not the serving size in your daily log. Label leftovers and follow local food-safety guidance for refrigeration, reheating and transport. If facilities are limited, ask for meals that fit those constraints.
ACTION (10–20s): Open your meal plan. Bring the recurring obstacle to your next check-in.','["Meal preparation for busy professionals", "The practical principle", "What the evidence can and cannot tell us", "Choose recipes you already enjoy and check your shopping list before cooking", "Your decision: Open your meal plan", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "NHS balanced eating guidance (general context)", "url": "https://www.nhs.uk/live-well/eat-well/how-to-eat-a-balanced-diet/eating-a-balanced-diet/"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['late-office','restaurants']::text[],'Nutrition Meal preparation for busy professionals busy work travel time','reviewed',true) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','poor-sleep','What to do after a poor night’s sleep','Check how you feel before training.','Recovery','workout','Check how you feel before training. Use an approved tired-day option if appropriate, or ask your coach about moving the session. Avoid chasing a personal best when alertness or technique is poor. Protect your next sleep opportunity rather than trying to solve the day with more stimulants.','One poor night and persistent sleep problems need different responses. Consider whether you can work, drive and train safely today. Tell your coach if fatigue is changing technique or recovery. Persistent unexplained tiredness, snoring with breathing pauses or repeated sleep disruption deserves medical advice, not a wearable-based diagnosis.','HOOK (5–10s): What to do after a poor night’s sleep
EXPLANATION (30–90s): Check how you feel before training. Use an approved tired-day option if appropriate, or ask your coach about moving the session. Avoid chasing a personal best when alertness or technique is poor. Protect your next sleep opportunity rather than trying to solve the day with more stimulants. One poor night and persistent sleep problems need different responses. Consider whether you can work, drive and train safely today. Tell your coach if fatigue is changing technique or recovery. Persistent unexplained tiredness, snoring with breathing pauses or repeated sleep disruption deserves medical advice, not a wearable-based diagnosis.
ACTION (10–20s): Preview a coach-approved workout option. Bring the recurring obstacle to your next check-in.','["What to do after a poor night’s sleep", "The practical principle", "What the evidence can and cannot tell us", "One poor night and persistent sleep problems need different responses", "Your decision: Preview a coach-approved workout option", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "NHS tiredness and fatigue", "url": "https://www.nhs.uk/symptoms/tiredness-and-fatigue/"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['stress','recovery']::text[],'Recovery What to do after a poor night’s sleep busy work travel time','reviewed',true) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','caffeine','Caffeine and energy management','Notice when and how much caffeine you use, especially later in the day.','Recovery','bookmark','Notice when and how much caffeine you use, especially later in the day. If it disrupts sleep, move the last serving earlier and review the pattern. Do not use escalating caffeine to push through persistent fatigue.','Sensitivity and sleep timing differ between people. Track the practical pattern rather than assuming a universal cut-off suits you. Consider caffeine in tea, coffee, energy drinks and some supplements. If reducing a large habitual intake, a gradual change may be easier. Pregnancy, medicines and heart symptoms need advice tailored by a qualified professional.','HOOK (5–10s): Caffeine and energy management
EXPLANATION (30–90s): Notice when and how much caffeine you use, especially later in the day. If it disrupts sleep, move the last serving earlier and review the pattern. Do not use escalating caffeine to push through persistent fatigue. Sensitivity and sleep timing differ between people. Track the practical pattern rather than assuming a universal cut-off suits you. Consider caffeine in tea, coffee, energy drinks and some supplements. If reducing a large habitual intake, a gradual change may be easier. Pregnancy, medicines and heart symptoms need advice tailored by a qualified professional.
