insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','weight-fluctuations','Why body weight fluctuates','A single weigh-in is not a verdict on your progress.','Progress','progress','A single weigh-in is not a verdict on your progress. Food, fluid, bowel contents and measurement timing can change the reading. If weighing is appropriate for you, compare measurements taken in similar conditions and discuss the longer pattern with your coach.','Do not change targets because of one higher reading. Use the measurements already agreed with your coach and consider attendance, performance and how the routine is working too. If weighing creates distress, discuss another way to review progress. Rapid unexplained changes, swelling or other symptoms should be assessed by a clinician.','HOOK (5–10s): Why body weight fluctuates
EXPLANATION (30–90s): A single weigh-in is not a verdict on your progress. Food, fluid, bowel contents and measurement timing can change the reading. If weighing is appropriate for you, compare measurements taken in similar conditions and discuss the longer pattern with your coach. Do not change targets because of one higher reading. Use the measurements already agreed with your coach and consider attendance, performance and how the routine is working too. If weighing creates distress, discuss another way to review progress. Rapid unexplained changes, swelling or other symptoms should be assessed by a clinician.
ACTION (10–20s): Review your progress. Bring the recurring obstacle to your next check-in.','["Why body weight fluctuates", "The practical principle", "What the evidence can and cannot tell us", "Do not change targets because of one higher reading", "Your decision: Review your progress", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "NHS healthy weight guidance (general context)", "url": "https://www.nhs.uk/live-well/healthy-weight/"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['progress-review','wearables']::text[],'Progress Why body weight fluctuates busy work travel time','reviewed',true) on conflict(coach_id,slug) where slug is not null do nothing;
insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','fat-loss-stall','What to do when fat loss stalls','Review several weeks with your coach before changing food targets.','Progress','support','Review several weeks with your coach before changing food targets. Check whether meals, activity and measurements have been consistent enough to interpret. Bring travel, missed logs and schedule changes into the discussion. Avoid aggressive cuts based on a few readings.','A plateau cannot be diagnosed from a single chart. Missing information can look like stalled progress, and measurement conditions can obscure a trend. Your coach should review goals, adherence, recovery and whether the plan remains appropriate. The Playbook explains the review process; it does not automatically reduce calories or add exercise.','HOOK (5–10s): What to do when fat loss stalls
EXPLANATION (30–90s): Review several weeks with your coach before changing food targets. Check whether meals, activity and measurements have been consistent enough to interpret. Bring travel, missed logs and schedule changes into the discussion. Avoid aggressive cuts based on a few readings. A plateau cannot be diagnosed from a single chart. Missing information can look like stalled progress, and measurement conditions can obscure a trend. Your coach should review goals, adherence, recovery and whether the plan remains appropriate. The Playbook explains the review process; it does not automatically reduce calories or add exercise.
ACTION (10–20s): Ask your coach. Bring the recurring obstacle to your next check-in.','["What to do when fat loss stalls", "The practical principle", "What the evidence can and cannot tell us", "A plateau cannot be diagnosed from a single chart", "Your decision: Ask your coach", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "NHS healthy weight guidance (general context)", "url": "https://www.nhs.uk/live-well/healthy-weight/"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['weight-fluctuations','progress-review','wearables']::text[],'Progress What to do when fat loss stalls busy work travel time','reviewed',false) on conflict(coach_id,slug) where slug is not null do nothing;
