insert into public.coaching_start_resources(coach_id,slug,title,description,category,action_kind,quick_answer,body,video_script,slide_outline,evidence,safety,related_slugs,keywords,review_status,published) values('56bd942e-7baa-42d3-a9c3-5eedcb33f1db','strength-aging','Why strength matters as you age','A consistent strength routine can support everyday function as you get older.','Health','training','A consistent strength routine can support everyday function as you get older. Start from the programme your coach assigned and progress at a manageable pace. The best starting point reflects your experience, health and equipment, rather than your age alone.','Strength training involves learning movements and gradually practising them with appropriate resistance. It should be adapted around existing limitations and recovery. Your coach can review technique, attendance and progression. New pain or a medical restriction needs individual assessment; general guidance is not medical clearance.','HOOK (5–10s): Why strength matters as you age
EXPLANATION (30–90s): A consistent strength routine can support everyday function as you get older. Start from the programme your coach assigned and progress at a manageable pace. The best starting point reflects your experience, health and equipment, rather than your age alone. Strength training involves learning movements and gradually practising them with appropriate resistance. It should be adapted around existing limitations and recovery. Your coach can review technique, attendance and progression. New pain or a medical restriction needs individual assessment; general guidance is not medical clearance.
ACTION (10–20s): Open your training. Bring the recurring obstacle to your next check-in.','["Why strength matters as you age", "The practical principle", "What the evidence can and cannot tell us", "Strength training involves learning movements and gradually practising them with appropriate resistance", "Your decision: Open your training", "Check your context and safety", "One next step"]'::jsonb,'[{"title": "WHO physical activity guidance (general context)", "url": "https://www.who.int/news-room/fact-sheets/detail/physical-activity"}]'::jsonb,'Use your individual plan and coach advice. Stop training if unwell or in pain; seek appropriate assessment. For food, check allergens and safe preparation. Persistent or concerning symptoms need clinical advice.',array['back-on-track','busy-habits']::text[],'Health Why strength matters as you age busy work travel time','reviewed',false) on conflict(coach_id,slug) where slug is not null do nothing;
